template <>
struct Codec<StellarMessage> {
  static constexpr std::uint64_t kMinSize = 8;
  static bool encode(const StellarMessage&, Encoder&);
  static bool decode(StellarMessage&, Decoder&);
  static bool gen(StellarMessage&, XdrRng&, std::uint32_t);
  template <typename F>
  static void visit_fields(const StellarMessage& v, F&& f) {
    f("type", v.t_);
    switch (v.t_) {
      case MessageType::ERROR_MSG:
        f("error", std::get<0>(v.v_));
        return;
      case MessageType::HELLO:
        f("hello", std::get<1>(v.v_));
        return;
      case MessageType::AUTH:
        f("auth", std::get<2>(v.v_));
        return;
      case MessageType::DONT_HAVE:
        f("dontHave", std::get<3>(v.v_));
        return;
      case MessageType::PEERS:
        f("peers", std::get<4>(v.v_));
        return;
      case MessageType::GET_TX_SET:
        f("txSetHash", std::get<5>(v.v_));
        return;
      case MessageType::TX_SET:
        f("txSet", std::get<6>(v.v_));
        return;
      case MessageType::GENERALIZED_TX_SET:
        f("generalizedTxSet", std::get<7>(v.v_));
        return;
      case MessageType::TRANSACTION:
        f("transaction", std::get<8>(v.v_));
        return;
      case MessageType::TIME_SLICED_SURVEY_REQUEST:
        f("signedTimeSlicedSurveyRequestMessage", std::get<9>(v.v_));
        return;
      case MessageType::TIME_SLICED_SURVEY_RESPONSE:
        f("signedTimeSlicedSurveyResponseMessage", std::get<10>(v.v_));
        return;
      case MessageType::TIME_SLICED_SURVEY_START_COLLECTING:
        f("signedTimeSlicedSurveyStartCollectingMessage", std::get<11>(v.v_));
        return;
      case MessageType::TIME_SLICED_SURVEY_STOP_COLLECTING:
        f("signedTimeSlicedSurveyStopCollectingMessage", std::get<12>(v.v_));
        return;
      case MessageType::GET_SCP_QUORUMSET:
        f("qSetHash", std::get<13>(v.v_));
        return;
      case MessageType::SCP_QUORUMSET:
        f("qSet", std::get<14>(v.v_));
        return;
      case MessageType::SCP_MESSAGE:
        f("envelope", std::get<15>(v.v_));
        return;
      case MessageType::GET_SCP_STATE:
        f("getSCPLedgerSeq", std::get<16>(v.v_));
        return;
      case MessageType::SEND_MORE:
        f("sendMoreMessage", std::get<17>(v.v_));
        return;
      case MessageType::SEND_MORE_EXTENDED:
        f("sendMoreExtendedMessage", std::get<18>(v.v_));
        return;
      case MessageType::FLOOD_ADVERT:
        f("floodAdvert", std::get<19>(v.v_));
        return;
      case MessageType::FLOOD_DEMAND:
        f("floodDemand", std::get<20>(v.v_));
        return;
      default: return;
    }
  }
};
